public class OverdueInvoiceBatch implements Database.Batchable<sObject>, Database.Stateful {

    private Integer recordsUpdated = 0;
    private Integer recordsFailed = 0;
    private Decimal overdueAmount = 0.0;

    public OverdueInvoiceBatch() {
        // No-argument constructor
    }

    public Database.QueryLocator start(Database.BatchableContext BC) {
        return Database.getQueryLocator([
            SELECT Id, Status__c, Due_Date__c, Amount__c, Customer_Email__c 
            FROM FB_Invoice__c 
            WHERE Status__c = 'Open' 
            AND Due_Date__c < TODAY
        ]);
    }

    public void execute(Database.BatchableContext BC, List<sObject> scope) {
        List<FB_Invoice__c> invoicesToUpdate = new List<FB_Invoice__c>();

        for (sObject obj : scope) {
            FB_Invoice__c invoice = (FB_Invoice__c)obj;
            invoice.Status__c = 'Overdue';
            invoicesToUpdate.add(invoice);
        }

        // Use Database.update with allOrNone=false to ensure partial success
        // This allows valid records to save even if some fail validation rules
        Database.SaveResult[] results = Database.update(invoicesToUpdate, false);

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (sr.isSuccess()) {
                recordsUpdated++;
                // Retrieve original amount from the scope list to calculate sum accurately
                Decimal amt = (Decimal)invoicesToUpdate[i].get('Amount__c');
                overdueAmount += (amt == null) ? 0.0 : amt;
            } else {
                recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext BC) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c(
            Job_Name__c = 'OverdueInvoiceBatch',
            Records_Updated__c = recordsUpdated,
            Records_Failed__c = recordsFailed,
            Overdue_Amount__c = overdueAmount
        );
        insert summary;
    }
}
