public with sharing class ContactTriggerHandler {

    public void handleBefore(List<Contact> newList, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newList) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource 
            FROM Account 
            WHERE Id IN :accountIds
        ]);

        for (Contact c : newList) {
            if (c.AccountId != null && accountMap.containsKey(c.AccountId)) {
                Account a = accountMap.get(c.AccountId);
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    public void handleAfterInsert(List<Contact> newList) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newList) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Query accounts to check current phone and identify which ones need updating
        Map<Id, Account> accountMap = new Map<Id, Account>([
            SELECT Id, Phone 
            FROM Account 
            WHERE Id IN :accountIds
        ]);

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();

        for (Contact c : newList) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                Account a = accountMap.get(c.AccountId);
                // If account exists in map and its phone is currently blank
                if (a != null && String.isBlank(a.Phone)) {
                    // Logic: "the first of those contacts (in trigger order) sets the account phone"
                    // Since we iterate through newList in order, the first contact that matches 
                    // the condition will populate the phone in our local map.
                    // Subsequent contacts will see 'a.Phone' as NOT blank because we update the map instance.
                    a.Phone = c.Phone;
                    accountsToUpdate.put(a.Id, a);

                    // Update the map entry so subsequent contacts in this loop see the "new" phone
                    // This ensures only the first contact effectively "sets" the phone.
                    accountMap.put(a.Id, a);
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
