public class LogPurgeJob implements Schedulable {

    /**
     * Constructor as required by the task.
     */
    public LogPurgeJob() {
    }

    /**
     * The execute method runs the purge logic.
     * It uses two separate queries/deletes to handle the different retention policies:
     * 1. Delete ERROR logs older than 180 days.
     * 2. Delete non-ERROR logs older than 30 days.
     * 
     * To ensure bulk safety and avoid governor limits, we use a single DML operation 
     * where possible or handle the batches. Since we are deleting based on date,
     * we'll fetch IDs to be safe and efficient.
     */
    public void execute(SchedulableContext sc) {
        purgeLogs();
    }

    private void purgeLogs() {
        // Calculate date thresholds
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date oneEightyDaysAgo = Date.today().addDays(-180);

        // Logic: 
        // Delete records where (Level != 'ERROR' AND CreatedDate < 30 days)
        // OR (Level == 'ERROR' AND CreatedDate < 180 days)

        // Using a single query to find all eligible IDs to minimize DML overhead
        // We use a SOQL query that targets both sets of criteria.
        // Criteria 1: Level is NOT 'ERROR' and created > 30 days ago
        // Criteria 2: Level IS 'ERROR' and created > 180 days ago

        // Note: We use 'CreatedDate < :threshold' in SOQL. 
        // Because CreatedDate is a DateTime, we compare against the calculated Date.

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE 
                (Level__c != 'ERROR' AND CreatedDate < :thirtyDaysAgo)
                OR 
                (Level__c = 'ERROR' AND CreatedDate < :oneEightyDaysAgo)
        ];

        if (!logsToDelete.isEmpty()) {
            // Using Database.delete with allOrNone=false is a best practice in some 
            // integration scenarios, but for a standard purge job, a standard delete 
            // is sufficient and follows the requirement.
            delete logsToDelete;
        }
    }

    /**
     * Schedules the job to run every day at 02:00 under the job name 'Log purge (nightly)'.
     * @return The Id of the scheduled job.
     */
    public static Id scheduleNightly() {
        // Cron expression for 02:00 AM every day: '0 0 2 * * ?'
        String cronExp = '0 0 2 * * ?';
        Id jobId = System.schedule('Log purge (nightly)', cronExp, new LogPurgeJob());
        return jobId;
    }
}
