public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct() {
            return new Opportunities();
        }
    }

    public Opportunities() {
        super(Opportunity.SObjectType);
    }

    public override void validate() {
        // Rule 1: Amount must not be negative on insert or update
        for (Opportunity opp : (List<Opportunity>) this.getRecords()) {
            if (opp.Amount < 0) {
                this.error('Amount cannot be negative.', opp, 'Amount');
            }
        }

        // Rule 2: Amount cannot change if Stage was already 'Closed Won'
        // We use getOldRecords() to compare against the state before the current transaction
        if (this.isUpdate()) {
            Map<Id, Opportunity> oldMap = (Map<Id, Opportunity>) this.getOldRecordsMap();
            for (Opportunity opp : (List<Opportunity>) this.getRecords()) {
                Opportunity oldOpp = oldMap.get(opp.Id);

                // Check if it was ALREADY Closed Won before this update
                if (oldOpp.StageName == 'Closed Won') {
                    // Check if Amount has changed
                    if (opp.Amount != oldOpp.Amount) {
                        this.error('Amount cannot change on a won opportunity.', opp, 'Amount');
                    }
                }
            }
        }
    }
}
