public with sharing class DealEventPublisher {

    /**
     * Publishes a Deal_Stage_Change__e platform event for each Opportunity provided.
     * 
     * Per requirement, this method calls EventBus.publish inside the loop to 
     * allow granular tracking of individual event success/failure via SaveResults.
     * 
     * @param opportunities A list of Opportunity records (typically from a trigger).
     * @return A list of Database.SaveResult objects corresponding to the input list.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        for (Opportunity opp : opportunities) {
            // Construct the event payload
            Deal_Stage_Change__e event = new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c = opp.StageName,
                Amount__c = opp.Amount
            );

            // Publish the event individually as requested to capture specific SaveResults
            // Note: In high-scale scenarios, bulkifying this (publishing a List) is 
            // usually preferred, but we are following the requirement for granular results.
            Database.SaveResult sr = EventBus.publish(event);
            results.add(sr);
        }

        return results;
    }
}
