/**
 * @description Service class to create follow-up tasks for a list of Opportunities.
 * Following the specific requirement to use individual DML statements to ensure 
 * that validation rule failures on one record do not prevent the creation of 
 * others.
 */
public with sharing class FollowUpTaskService {

    /**
     * @description Creates a follow-up task for each provided Opportunity ID.
     * @param opportunityIds A list of Opportunity IDs to process.
     * @return A Set of Opportunity IDs for which the task creation failed.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Fetch Opportunity details needed for Task creation
        // Using a Map to easily correlate Opportunity data with the IDs provided
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Name, OwnerId 
            FROM Opportunity 
            WHERE Id IN :opportunityIds
        ]);

        for (Id oppId : opportunityIds) {
            // Handle case where an ID might be passed that doesn't exist in the DB
            if (!oppMap.containsKey(oppId)) {
                failedOpportunityIds.add(oppId);
                continue;
            }

            Opportunity opp = oppMap.get(oppId);

            // Initialize the Task
            Task followUpTask = new Task(
                WhatId = opp.Id,
                OwnerId = opp.OwnerId,
                Subject = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal'
            );

            try {
                // Per instructions: individual insert to bypass bulk failure via validation rules
                insert followUpTask;
            } catch (Exception e) {
                // If insertion fails due to validation rules or other errors, 
                // capture the original Opportunity ID.
                failedOpportunityIds.add(oppId);
            }
        }

        return failedOpportunityIds;
    }
}
