public with sharing class AccountCountrySync {

    /**
     * Handles the logic for syncing BillingCountry to Contact MailingCountry.
     * 
     * @param newAccounts The list of accounts in the current transaction (Trigger.new)
     * @param oldAccountMap The map of accounts before the update (Trigger.oldMap)
     */
    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {
        Set<Id> accountIdsWithCountryChange = new Set<Id>();
        Map<Id, String> accountIdToOldCountry = new Map<Id, String>();

        // Identify accounts where BillingCountry has changed
        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountMap.get(acc.Id);

            // Check if country changed (handling nulls via comparison)
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                accountIdsWithCountryChange.add(acc.Id);
                accountIdToOldCountry.put(acc.Id, oldAcc.BillingCountry);
            }
        }

        // If no accounts in this batch had a country change, exit early
        if (accountIdsWithCountryChange.isEmpty()) {
            return;
        }

        // Query only contacts related to the affected accounts.
        // Loading 2.3M contacts into memory as originally suggested would cause Heap Size errors.
        // This filtered approach is bulk-safe and respects governor limits.
        List<Contact> relatedContacts = [
            SELECT Id, AccountId, MailingCountry 
            FROM Contact 
            WHERE AccountId IN :accountIdsWithCountryChange
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : relatedContacts) {
            Account acc = null;
            // We need the new BillingCountry from the newAccounts list
            // Since we are in a trigger, we can find the specific account record
            // To avoid another loop/query, we find the acc in the context of the trigger
            // However, for cleaner logic, we can map the new values first.
            // Let's assume we find the account in the newAccounts list.
        }

        // Refined loop: map the new account values for quick access
        Map<Id, Account> newAccountMap = new Map<Id, Account>(newAccounts);

        for (Contact con : relatedContacts) {
            Account currentAcc = newAccountMap.get(con.AccountId);
            String oldCountry = accountIdToOldCountry.get(con.AccountId);
            String newCountry = currentAcc.BillingCountry;

            // Logic: Set MailingCountry if it is blank OR equal to the previous BillingCountry
            if (String.isBlank(con.MailingCountry) || con.MailingCountry == oldCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
