import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleInputChange(event) {
        const field = event.target.dataset.field;
        const value = event.target.value;

        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    async handleRegister() {
        const emailInput = this.template.querySelector('[data-field="email"]');
        const fullNameInput = this.template.querySelector('[data-field="fullName"]');
        const companyInput = this.template.querySelector('[data-field="company"]');
        const allInputs = [emailInput, fullNameInput, companyInput];

        // 1. Work email validation
        const forbiddenDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
        const emailValue = this.email.toLowerCase();
        const domain = emailValue.split('@')[1];

        if (forbiddenDomains.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // 2. Report validity for all inputs
        allInputs.forEach(input => {
            if (input) {
                input.reportValidity();
            }
        });

        // 3. Check if valid
        const isInvalid = allInputs.some(input => input && !input.checkValidity());
        if (isInvalid) {
            return;
        }

        // 4. Call Apex
        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });

            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
                    message: error.body ? error.body.message : error.message
                })
            );
        }
    }
}
