        return this._value;
    }
    set value(val) {
        this._value = val;
        // Sync active index if the external value changes
        const index = this.options.findIndex(opt => opt.value === val);
        if (index !== -1) {
            this.activeIndex = index;
        } else if (this.options.length > 0 && index === -1) {
            // If the new value isn't in the list, default to first option focus if needed
            // but the requirement says: "When the parent changes value, the active option moves to it."
            // If the value provided doesn't exist, we keep activeIndex as is or follow logic.
            // We'll assume if it's not found, we don't move activeIndex unless it's the first valid option.
        }
    }

    _value;
    activeIndex = 0;

    get activeDescendantId() {
        if (this.options.length === 0) return '';
        return `option-${this.activeIndex}`;
    }

    get optionsData() {
        // Ensure activeIndex is valid for the current options length
        if (this.activeIndex >= this.options.length) {
            this.activeIndex = Math.max(0, this.options.length - 1);
        }
        return this.options;
    }

    handleKeyDown(event) {
        let newIndex = this.activeIndex;
        let handled = true;

        switch (event.key) {
            case 'ArrowDown':
                if (this.activeIndex < this.options.length - 1) {
                    newIndex++;
                }
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    newIndex--;
                }
                break;
            case 'Home':
                newIndex = 0;
                break;
            case 'End':
                newIndex = this.options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.handleSelect(this.options[this.activeIndex]?.value);
                break;
            default:
                handled = false;
                break;
        }

        if (handled) {
            event.preventDefault();
            if (newIndex !== this.activeIndex) {
                this.activeIndex = newIndex;
            }
        }
    }

    handleOptionClick(event) {
        const val = event.currentTarget.dataset.value;
        const index = this.options.findIndex(opt => opt.value === val);
        if (index !== -1) {
            this.activeIndex = index;
            this.handleSelect(val);
        }
    }

    handleSelect(val) {
        if (val !== this._value) {
            this._value = val;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: val }
            }));
        }
    }
