public with sharing class FamilyService {
    /**
     * Links parents to children in NPSP.
     * 
     * @param parentIdByChildId Map where key is Child Contact Id and value is Parent Contact Id.
     * 
     * NPSP Relationships work by creating a record in the npsp__Relationship__c object.
     * To ensure reciprocity based on List Settings:
     * 1. We create the relationship record representing the 'Parent' role for the child.
     * 2. NPSP's reciprocal logic (via triggers) will automatically create/handle the 
     *    reciprocal record (Son/Daughter/Child) for the parent.
     * 
     * However, the requirement states: "Each pair must end up with exactly one relationship 
     * record in each direction." In NPSP, a single Relationship record with a reciprocal 
     * definition creates the reciprocal link automatically. To avoid duplicate 
     * relationship records or conflicts, we must ensure no relationship exists between 
     * these two contacts before inserting.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Set of all Contact IDs involved to filter existing relationships
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            allContactIds.add(childId);
            allContactIds.add(parentIdByChildId.get(childId));
        }

        // Query existing relationships between these contacts to prevent duplicates.
        // We check both Contact1 and Contact2 to see if a relationship already exists 
        // in either direction between any pair in our input.
        // To do this efficiently in 1 SOQL, we find all relationships where both participants
        // are in our set of contact IDs.
        Set<String> existingRelationshipKeys = new Set<String>();

        for (npsp__Relationship__c rel : [
            SELECT Id, npsp__Contact1__c, npsp__Contact2__c 
            FROM npsp__Relationship__c 
            WHERE npsp__Contact1__c IN :allContactIds 
            AND npsp__Contact2__c IN :allContactIds
        ]) {
            // Create a unique key for the pair (sorted) to easily check existence
            Id c1 = rel.npsp__Contact1__c;
            Id c2 = rel.npsp__Contact2__c;
            existingRelationshipKeys.add(c1 < c2 ? c1 + '_' + c2 : c2 + '_' + c1);
        }

        // Identify the Relationship Type Id for 'Parent'
        // In a production environment, we would ideally query this or use a Custom Setting/Metadata.
        // Since we cannot assume the exact ID, we find the record where the name is 'Parent'.
        // However, the requirement implies we are configuring the link. 
        // We must find the Relationship Type ID for 'Parent'.
        Id parentRelTypeId = null;
        for (npsp__Relationship_Type__c relType : [SELECT Id, Name FROM npsp__Relationship_Type__c WHERE Name = 'Parent' LIMIT 1]) {
            parentRelTypeId = relType.Id;
            break;
        }

        // If 'Parent' relationship type doesn't exist, we can't proceed.
        if (parentRelTypeId == null) {
            return;
        }

        List<npsp__Relationship__c> newRelationships = new List<npsp__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (parentId == null || childId == parentId) {
                continue;
            }

            // Check if a relationship already exists between this pair
            String pairKey = childId < parentId ? childId + '_' + parentId : parentId + '_' + childId;
            if (existingRelationshipKeys.contains(pairKey)) {
                continue;
            }

            // Create the relationship. 
            // npsp__Contact1__c is usually the 'Subject' and npsp__Contact2__c is the 'Object'.
            // To make the child have the parent as a 'Parent', the child is the Subject (Contact1).
            newRelationships.add(new npsp__Relationship__c(
                npsp__Contact1__c = childId,
                npsp__Contact2__c = parentId,
                npsp__Relationship_Type__c = parentRelTypeId,
                npsp__Status__c = 'Current'
            ));
        }

        if (!newRelationships.isEmpty()) {
            insert newRelationships;
        }
    }
}
