public with sharing class TA_Account_CreateOnboardingTask {

    /**
     * Implementation of the Trigger Action Framework pattern.
     * This class handles the creation of onboarding tasks for specific Account types upon insertion.
     */
    public static void execute(List<Account> newList, Map<Id, Account> oldMap) {
        List<Task> tasksToInsert = new List<Task>();
        Set<String> validTypes = new Set<String>{'Customer - Direct', 'Customer - Channel'};

        for (Account acc : newList) {
            // Only process on creation (oldMap will be null in an Insert context) 
            // and only if Type matches requirements
            if (acc.Type != null && validTypes.contains(acc.Type)) {
                tasksToInsert.add(new Task(
                    Subject = 'Onboard new customer',
                    WhatId = acc.Id,
                    OwnerId = acc.OwnerId,
                    ActivityDate = Date.today().addDays(7),
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
```

