public with sharing class TA_Opportunity_CollectForErpSync implements Trigger_Action.Action {
    private static final Set<Id> idsToSync = new Set<Id>();

    public void execute(Trigger.TriggerContext context) {
        if (context.Trigger.new == null) {
            return;
        }

        for (Opportunity opp : (List<Opportunity>) context.Trigger.new) {
            Boolean shouldSync = false;

            if (context.TriggerOperation == Trigger.Operation.AFTER_INSERT) {
                shouldSync = true;
            } else if (context.TriggerOperation == Trigger.Operation.AFTER_UPDATE) {
                // Check if StageName has changed
                Opportunity oldOpp = (Opportunity) context.Trigger.oldMap.get(opp.Id);
                if (opp.StageName != oldOpp.StageName) {
                    shouldSync = true;
                }
            }

            if (shouldSync) {
                idsToSync.add(opp.Id);
            }
        }
    }

    public static Set<Id> getIdsToSync() {
        return idsToSync;
    }
}
```

