public with sharing class OpportunityErpSyncFinalizer implements Trigger_Action.DML_Finalizer {
    public void execute(Trigger.TriggerContext context) {
        // The finalizer is called for every DML operation the framework handles.
        // We only care about Opportunity context for this specific business logic.
        if (context.SObjectType != Opportunity.SObjectType) {
            return;
        }

        // TAF collects Ids via the Action class into a static set.
        // We access the static method from the specific Action class.
        Set<Id> idsToSync = TA_Opportunity_CollectForErpSync.getIdsToSync();

        if (idsToSync != null && !idsToSync.isEmpty()) {
            System.enqueueJob(new OpportunityErpSyncJob(idsToSync));
        }
    }
}
